function m(){return localStorage.getItem("cloud_pos_timezone")||"Asia/Jakarta"}function s(t){const n=Number(t)||0;return new Intl.NumberFormat("id-ID",{style:"currency",currency:"IDR",minimumFractionDigits:0,maximumFractionDigits:0}).format(n)}function c(t){if(!t)return"—";const n=new Date(t),e=m(),i=new Intl.DateTimeFormat("en-GB",{year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",hour12:!1,timeZone:e}).formatToParts(n),r=a=>{var o;return((o=i.find(u=>u.type===a))==null?void 0:o.value)||""};return`${r("day")}-${r("month")}-${r("year")}, ${r("hour")}:${r("minute")}`}function f(){const t=m(),n=new Intl.DateTimeFormat("en-CA",{year:"numeric",month:"2-digit",day:"2-digit",timeZone:t}).formatToParts(new Date),e=i=>{var r;return((r=n.find(a=>a.type===i))==null?void 0:r.value)||""};return`${e("year")}-${e("month")}-${e("day")}`}function d(t){if(!t||typeof t!="string")return"—";const e=(t.includes("T")?t.split("T")[0]:t).split("-");return e.length!==3?t:`${e[2]}-${e[1]}-${e[0]}`}function g(t){if(!t)return"—";const n=(Date.now()-new Date(t).getTime())/1e3;return n<60?"baru saja":n<3600?`${Math.floor(n/60)} menit lalu`:n<86400?`${Math.floor(n/3600)} jam lalu`:`${Math.floor(n/86400)} hari lalu`}export{c as a,f as b,d as c,s as f,g as t};
